const config = $items("Template Config", 0, 0)[0]?.json ?? {};
const users = $json.data?.items || [];
const timezone = config.timezone || 'Asia/Ho_Chi_Minh';

function getZonedParts(date, timeZone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).formatToParts(date);

  const values = {};
  for (const part of parts) {
    if (part.type !== 'literal') values[part.type] = part.value;
  }

  return {
    year: Number(values.year),
    month: Number(values.month),
    day: Number(values.day),
    hour: Number(values.hour),
    minute: Number(values.minute),
    second: Number(values.second),
  };
}

function getTimeZoneOffsetMs(date, timeZone) {
  const zoned = getZonedParts(date, timeZone);
  const asUtc = Date.UTC(zoned.year, zoned.month - 1, zoned.day, zoned.hour, zoned.minute, zoned.second);
  return asUtc - date.getTime();
}

function getTodayUnixRange(timeZone) {
  const now = new Date();
  const zonedNow = getZonedParts(now, timeZone);

  const startGuess = new Date(Date.UTC(zonedNow.year, zonedNow.month - 1, zonedNow.day, 0, 0, 0, 0));
  const endGuess = new Date(Date.UTC(zonedNow.year, zonedNow.month - 1, zonedNow.day, 23, 59, 59, 999));

  const startOffset = getTimeZoneOffsetMs(startGuess, timeZone);
  const endOffset = getTimeZoneOffsetMs(endGuess, timeZone);

  return {
    start: Math.floor((startGuess.getTime() - startOffset) / 1000),
    end: Math.floor((endGuess.getTime() - endOffset) / 1000),
  };
}

const { start, end } = getTodayUnixRange(timezone);

return users.map((user) => ({
  json: {
    user_id: user.user_id,
    open_id: user.open_id,
    name: user.name,
    email: user.email ?? null,
    mobile: user.mobile ?? null,
    queryStartSec: start,
    queryEndSec: end,
    timezone,
  },
}));

const config = $items("Template Config", 0, 0)[0]?.json ?? {};
const inputItems = await $input.all();
const users = $items("Normalize User Fields").map((item) => item.json);
const timezone = config.timezone || 'Asia/Ho_Chi_Minh';
const batchSize = Number(config.bitableBatchSize || 500);

const FIELD_NAMES = {
  employee: 'Employee',
  checkInTime: 'Check In Time',
  checkOutTime: 'Check Out Time',
  checkInComment: 'Check In Comment',
  checkOutComment: 'Check Out Comment',
  locationCheckin: 'Check In Location',
  employeeCode: 'Employee Code',
  checkinStatus: 'Check In Status',
  checkoutStatus: 'Check Out Status',
};

const STATUS_VALUES = {
  onTime: 'On-time',
  late: 'Late',
  veryLate: 'Very Late (0.5 Day Leave)',
  earlyOut: 'Early Out',
};

function parseHm(value, fallbackMinutes) {
  if (!value || typeof value !== 'string' || !value.includes(':')) return fallbackMinutes;
  const [hours, minutes] = value.split(':').map(Number);
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return fallbackMinutes;
  return hours * 60 + minutes;
}

const onTimeCutoff = parseHm(config.checkInOnTimeCutoff, 9 * 60 + 30);
const lateCutoff = parseHm(config.checkInLateCutoff, 10 * 60);
const checkoutExpectedMinutes = parseHm(config.checkOutExpectedTime, 18 * 60);

function zonedMinutesFromUnix(sec) {
  const date = new Date(Number(sec) * 1000);
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: timezone,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(date);

  const hh = parseInt(parts.find((part) => part.type === 'hour').value, 10);
  const mm = parseInt(parts.find((part) => part.type === 'minute').value, 10);
  return hh * 60 + mm;
}

function classifyCheckin(checkInSec) {
  const minutes = zonedMinutesFromUnix(checkInSec);
  if (minutes > 12 * 60) return '';
  if (minutes <= onTimeCutoff) return 'On-time';
  if (minutes <= lateCutoff) return 'Late';
  return 'Very-late';
}

function classifyCheckout(checkOutSec) {
  if (!checkOutSec) return '';
  const minutes = zonedMinutesFromUnix(checkOutSec);
  return minutes < checkoutExpectedMinutes ? 'Early Out' : '';
}

function statusToSelectName(status) {
  if (!status) return null;
  if (status === 'On-time') return STATUS_VALUES.onTime;
  if (status === 'Late') return STATUS_VALUES.late;
  if (status === 'Very-late') return STATUS_VALUES.veryLate;
  return null;
}

function checkoutStatusName(status) {
  if (status === 'Early Out') return STATUS_VALUES.earlyOut;
  return status || '';
}

function workDate(sec) {
  const date = new Date(Number(sec) * 1000);
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: timezone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date);
}

function toMs(secOrStr) {
  const value = Number(secOrStr);
  if (!Number.isFinite(value) || value <= 0) return null;
  return Math.trunc(value * 1000);
}

function buildUserValue(openId, email) {
  if (openId) return [{ id: String(openId) }];
  if (email) return [{ email: String(email) }];
  return undefined;
}

function chunk(array, size) {
  const output = [];
  for (let index = 0; index < array.length; index += size) {
    output.push(array.slice(index, index + size));
  }
  return output;
}

const userMap = {};
for (const user of users) {
  userMap[String(user.user_id)] = {
    open_id: user.open_id || '',
    name: user.name || '',
    email: user.email || '',
    mobile: user.mobile || '',
  };
}

const grouped = {};
for (const item of inputItems) {
  const results = item.json?.data?.user_flow_results ?? [];
  for (const record of results) {
    record.user_id = String(record.user_id);
    const day = workDate(record.check_time);
    const key = `${record.user_id}_${day}`;
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(record);
  }
}

const normalized = [];
for (const records of Object.values(grouped)) {
  records.sort((a, b) => Number(a.check_time) - Number(b.check_time));
  const first = records[0];
  const last = records[records.length - 1];
  const hasCheckOut = records.length > 1;
  const user = userMap[String(first.user_id)] || {};

  normalized.push({
    user_id: first.user_id,
    open_id: user.open_id || first.open_id || '',
    name: user.name || first.name || '',
    email: user.email || first.email || '',
    mobile: user.mobile || first.mobile || '',
    location_name: first.location_name || '',
    work_date: workDate(first.check_time),
    check_in_time: first.check_time,
    check_out_time: hasCheckOut ? last.check_time : '',
    check_in_comment: first.comment || '',
    check_out_comment: hasCheckOut ? (last.comment || '') : '',
    status_checkin: classifyCheckin(first.check_time),
    status_checkout: classifyCheckout(hasCheckOut ? last.check_time : null),
    creator_id: first.creator_id ?? undefined,
  });
}

normalized.sort((a, b) => {
  const dateCompare = String(a.work_date).localeCompare(String(b.work_date));
  if (dateCompare !== 0) return dateCompare;
  return (a.name || '').localeCompare(b.name || '');
});

const records = normalized.map((entry) => {
  const checkinStatus = statusToSelectName(entry.status_checkin);
  const checkoutStatus = checkoutStatusName(entry.status_checkout);
  const fields = {
    [FIELD_NAMES.employee]: buildUserValue(entry.open_id, entry.email),
    [FIELD_NAMES.checkInTime]: toMs(entry.check_in_time),
    [FIELD_NAMES.checkOutTime]: toMs(entry.check_out_time),
    [FIELD_NAMES.checkInComment]: entry.check_in_comment ?? '',
    [FIELD_NAMES.checkOutComment]: entry.check_out_comment ?? '',
    [FIELD_NAMES.locationCheckin]: entry.location_name ?? '',
    [FIELD_NAMES.employeeCode]: entry.creator_id != null ? String(entry.creator_id) : '',
  };

  if (checkinStatus) fields[FIELD_NAMES.checkinStatus] = checkinStatus;
  if (checkoutStatus) fields[FIELD_NAMES.checkoutStatus] = checkoutStatus;

  for (const key of Object.keys(fields)) {
    if (fields[key] === undefined) delete fields[key];
  }

  return { fields };
});

return chunk(records, batchSize).map((batchedRecords) => ({
  json: { records: batchedRecords },
}));
